"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[34907],{3331:(e,a,s)=>{s.d(a,{R:()=>r,x:()=>l});var i=s(36672);const n={},o=i.createContext(n);function r(e){const a=i.useContext(o);return i.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function l(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(o.Provider,{value:a},e.children)}},63660:(e,a,s)=>{s.r(a),s.d(a,{assets:()=>d,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>i,toc:()=>t});const i=JSON.parse('{"id":"2023/04/10","title":"2023-04-10","description":"El efecto LLama: La filtraci\xf3n provoc\xf3 una serie de alternativas de c\xf3digo abierto a ChatGPT","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/2023/04/10.md","sourceDirName":"2023/04","slug":"/2023/04/10","permalink":"/es/2023/04/10","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/es/docusaurus-plugin-content-docs//current/2023/04/10.md","tags":[],"version":"current","frontMatter":{"localized_date":"10 de abril de 2023","top_news":"El efecto LLama: La filtraci\xf3n provoc\xf3 una serie de alternativas de c\xf3digo abierto a ChatGPT"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-11","permalink":"/es/2023/04/11"},"next":{"title":"2023-04-09","permalink":"/es/2023/04/09"}}');var n=s(23420),o=s(3331);const r={localized_date:"10 de abril de 2023",top_news:"El efecto LLama: La filtraci\xf3n provoc\xf3 una serie de alternativas de c\xf3digo abierto a ChatGPT"},l="2023-04-10",d={},t=[{value:"El efecto LLama: La filtraci\xf3n provoc\xf3 una serie de alternativas de c\xf3digo abierto a ChatGPT",id:"el-efecto-llama-la-filtraci\xf3n-provoc\xf3-una-serie-de-alternativas-de-c\xf3digo-abierto-a-chatgpt",level:2},{value:"\xbfDel aprendizaje profundo al largo?",id:"del-aprendizaje-profundo-al-largo",level:2},{value:"Se proh\xedbe a EY realizar nuevas auditor\xedas en Alemania",id:"se-proh\xedbe-a-ey-realizar-nuevas-auditor\xedas-en-alemania",level:2},{value:"Puesta de sol en el Polo Sur",id:"puesta-de-sol-en-el-polo-sur",level:2},{value:"Un periodista holand\xe9s cr\xedtico con China, objetivo de un plan de intimidaci\xf3n",id:"un-periodista-holand\xe9s-cr\xedtico-con-china-objetivo-de-un-plan-de-intimidaci\xf3n",level:2},{value:"Las instalaciones de USPS en Utah no hacen m\xe1s que descifrar la escritura a mano",id:"las-instalaciones-de-usps-en-utah-no-hacen-m\xe1s-que-descifrar-la-escritura-a-mano",level:2},{value:"Apple contin\xfaa sus esfuerzos para evitar que las tiendas minoristas se sindicalicen",id:"apple-contin\xfaa-sus-esfuerzos-para-evitar-que-las-tiendas-minoristas-se-sindicalicen",level:2},{value:"PL/Rust 1.0: ahora un lenguaje de confianza para Postgres",id:"plrust-10-ahora-un-lenguaje-de-confianza-para-postgres",level:2},{value:"Twitter Est\xe1 Bloqueando Likes y Retweets que Mencionan Substack",id:"twitter-est\xe1-bloqueando-likes-y-retweets-que-mencionan-substack",level:2},{value:"Z-Library permitir\xe1 a los usuarios compartir libros f\xedsicos",id:"z-library-permitir\xe1-a-los-usuarios-compartir-libros-f\xedsicos",level:2},{value:"Perseus - Alternativa a NextJS en Rust",id:"perseus---alternativa-a-nextjs-en-rust",level:2},{value:"A Baby GPT",id:"a-baby-gpt",level:2},{value:"Dos tipos de ingenieros de software",id:"dos-tipos-de-ingenieros-de-software",level:2},{value:"Programaci\xf3n avanzada en Linux (2001)",id:"programaci\xf3n-avanzada-en-linux-2001",level:2},{value:"Un CERN para la IA a gran escala de c\xf3digo abierto",id:"un-cern-para-la-ia-a-gran-escala-de-c\xf3digo-abierto",level:2},{value:"Permafrost engine - Un motor de juego OpenGL RTS escrito en C",id:"permafrost-engine---un-motor-de-juego-opengl-rts-escrito-en-c",level:2},{value:"Cierre de una conexi\xf3n SSH obsoleta.",id:"cierre-de-una-conexi\xf3n-ssh-obsoleta",level:2},{value:"Flatcar Container Linux",id:"flatcar-container-linux",level:2},{value:"Microsoft / JARVIS: un sistema para conectar LLMs con la comunidad ML",id:"microsoft--jarvis-un-sistema-para-conectar-llms-con-la-comunidad-ml",level:2},{value:"Un tokamak esf\xe9rico alcanza temperaturas de plasma cruciales",id:"un-tokamak-esf\xe9rico-alcanza-temperaturas-de-plasma-cruciales",level:2},{value:"Los primeros &#39;huevos de Pascua&#39; del juego fueron un acto de rebeld\xeda empresarial",id:"los-primeros-huevos-de-pascua-del-juego-fueron-un-acto-de-rebeld\xeda-empresarial",level:2},{value:"Errores modulares en Rust",id:"errores-modulares-en-rust",level:2},{value:"Regla 68-95-99.7",id:"regla-68-95-997",level:2},{value:"UnicodePlots",id:"unicodeplots",level:2},{value:"Digital collectibles on Instagram is winding down",id:"digital-collectibles-on-instagram-is-winding-down",level:2},{value:"La sentencia que amenaza el futuro de las bibliotecas",id:"la-sentencia-que-amenaza-el-futuro-de-las-bibliotecas",level:2},{value:"Do Kwon convirti\xf3 fondos il\xedcitos de LUNA a Bitcoin",id:"do-kwon-convirti\xf3-fondos-il\xedcitos-de-luna-a-bitcoin",level:2},{value:"Entrevista con Andrew Kelley (creador de Zig) (2021)",id:"entrevista-con-andrew-kelley-creador-de-zig-2021",level:2},{value:"Supavisor - un pooler de conexiones Postgres escrito en Elixir",id:"supavisor---un-pooler-de-conexiones-postgres-escrito-en-elixir",level:2},{value:"Nuevas acusaciones de plagio contra Roy Lichtenstein",id:"nuevas-acusaciones-de-plagio-contra-roy-lichtenstein",level:2}];function c(e){const a={a:"a",del:"del",h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.header,{children:(0,n.jsx)(a.h1,{id:"2023-04-10",children:"2023-04-10"})}),"\n",(0,n.jsx)(a.h2,{id:"el-efecto-llama-la-filtraci\xf3n-provoc\xf3-una-serie-de-alternativas-de-c\xf3digo-abierto-a-chatgpt",children:"El efecto LLama: La filtraci\xf3n provoc\xf3 una serie de alternativas de c\xf3digo abierto a ChatGPT"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://thesequence.substack.com/p/the-llama-effect-how-an-accidental",children:"Original"}),'.\nLa filtraci\xf3n accidental de "Llama", un modelo LLM, ha desencadenado un movimiento alternativo de c\xf3digo abierto a modelos como GPT-4 y Cohere, que s\xf3lo est\xe1n disponibles a trav\xe9s de API. Desde la filtraci\xf3n, se han publicado Alpaca, Vicuna, Koala, ColossalChat y ChatLLama, entre otros modelos, todos ellos basados en Llama. Las alternativas de c\xf3digo abierto a estos modelos no han mostrado el mismo nivel de rendimiento hasta el lanzamiento de Llama. La filtraci\xf3n de Llama ha resultado ser una de las mayores chispas de innovaci\xf3n en el espacio LLM de c\xf3digo abierto, donde se avecina una guerra entre la distribuci\xf3n de c\xf3digo abierto y la basada en API. El efecto Llama ha demostrado que el c\xf3digo abierto es un mecanismo de distribuci\xf3n viable para los modelos fundacionales, y existen algunas fuentes interesantes de innovaci\xf3n en el espacio LLM.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35504428",children:"Discussion Service"}),'.\nLa filtraci\xf3n del "efecto LLama" ha provocado la aparici\xf3n de alternativas de c\xf3digo abierto a ChatGPT, lo que ha atra\xeddo la atenci\xf3n de los expertos en tecnolog\xeda. GPT-4 demuestra una inteligencia m\xe1s significativa, ofreciendo capacidades de razonamiento y generalizaci\xf3n de su predecesor, GPT-3. Los modelos de s\xf3lo texto de AI comprenden el razonamiento espacial y pueden entender rompecabezas, pero es necesario un ajuste manual. Existe un debate en torno al nivel real de aprendizaje de los modelos ling\xfc\xedsticos, con la esperanza de un futuro de IA accesible y democratizado. La filtraci\xf3n de LLaMA ha propiciado la optimizaci\xf3n de c\xf3digo abierto en todas las plataformas; sin embargo, los expertos critican la pirater\xeda de software y la regulaci\xf3n de las empresas de IA. OpenAI puede enfrentarse a desaf\xedos legales por utilizar modelos para entrenar resultados comerciales. La precisi\xf3n de ChatGPT es divergente: algunos la consideran in\xfatil, mientras que otros afirman que GPT-4 mejora en algunos aspectos. Bing/Sydney y ChatGPT tienen personalidades diferentes. El post no aporta nuevos datos tecnol\xf3gicos, sino que discute la naturaleza de la compresi\xf3n de texto.']}),"\n",(0,n.jsx)(a.h2,{id:"del-aprendizaje-profundo-al-largo",children:"\xbfDel aprendizaje profundo al largo?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://hazyresearch.stanford.edu/blog/2023-03-27-long-learning",children:"Original"}),".\nLos investigadores de Stanford del laboratorio Hazy Research est\xe1n mejorando la longitud de las secuencias en los modelos de fundamentos de aprendizaje autom\xe1tico, centr\xe1ndose en la creaci\xf3n de modelos de tiempo casi lineal en la longitud de las secuencias que pueden conducir a longitudes de contexto de millones o incluso miles de millones. El modelo Hyena tiene escalabilidad en longitud de secuencia de hasta 2k utilizando una peque\xf1a red neuronal que parametriza los filtros convolucionales impl\xedcitamente a trav\xe9s de otra peque\xf1a red neuronal con un tiempo de implementaci\xf3n de O(NlogN). Los investigadores est\xe1n explorando las matrices de aprendizaje y su conexi\xf3n con las aplicaciones ling\xfc\xedsticas. N/A."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35502187",children:"Discussion Service"}),".\nInvestigadores de Stanford exploran la reducci\xf3n de costes para la autoatenci\xf3n en secuencias largas. La optimizaci\xf3n del c\xe1lculo para GPU y coprocesadores puede optimizar las LLM. Escepticismo en torno a los modelos de contexto m\xe1s largo, el acoplamiento de los LLM con otros sistemas puede crear nuevas soluciones. La publicaci\xf3n de GPT-4 da lugar a nuevas investigaciones sobre la predicci\xf3n del siguiente token y posibles avances en la memoria asociativa a largo plazo. La comprensi\xf3n de la representaci\xf3n K,Q,V es crucial, mientras que las RNN y los transformadores tienen implicaciones para la democratizaci\xf3n de la IA. Los contextos m\xe1s largos pueden considerarse una nueva forma de b\xfasqueda."]}),"\n",(0,n.jsx)(a.h2,{id:"se-proh\xedbe-a-ey-realizar-nuevas-auditor\xedas-en-alemania",children:"Se proh\xedbe a EY realizar nuevas auditor\xedas en Alemania"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.economist.com/business/2023/04/05/ey-gets-banned-from-new-audit-business-in-germany",children:"Original"}),".\nA EY se le ha prohibido durante dos a\xf1os auditar a nuevos clientes que coticen en bolsa en Alemania, ya que APAS, el organismo de control contable alem\xe1n, le ha impuesto una multa de 500.000 euros junto con la sanci\xf3n m\xe1s severa jam\xe1s impuesta. La decisi\xf3n, que llega despu\xe9s de una investigaci\xf3n de tres a\xf1os sobre el papel de EY en el esc\xe1ndalo Wirecard, ha infligido un importante golpe financiero y de reputaci\xf3n al asediado gigante de la contabilidad. EY hab\xeda dado a Wirecard el visto bueno hasta que la empresa se hundi\xf3 en 2020 en medio de acusaciones de fraude financiero masivo. Tras el esc\xe1ndalo de Wirecard, EY ha prometido invertir hasta 2.000 millones de d\xf3lares en tres a\xf1os para mejorar las auditor\xedas relacionadas con la tecnolog\xeda y la detecci\xf3n del fraude, pero es probable que ning\xfan auditor acierte siempre."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501937",children:"Discussion Service"}),'.\nSe ha prohibido a Ernst & Young (EY) realizar nuevas auditor\xedas en Alemania debido a decisiones de auditor\xeda incorrectas y a su implicaci\xf3n en el esc\xe1ndalo Wirecard. Las consultoras subcontratan a personal peor pagado para minimizar el riesgo, pero esto puede ser contraproducente. Los auditores solo ofrecen una seguridad razonable y no garantizan que no se produzcan fraudes. El uso de la automatizaci\xf3n y la IA puede ayudar a detectar actividades fraudulentas. La auditor\xeda debe separarse de la consultor\xeda para evitar conflictos de intereses. Hay debate sobre el valor de las consultoras y la necesidad de "piel en el juego".']}),"\n",(0,n.jsx)(a.h2,{id:"puesta-de-sol-en-el-polo-sur",children:"Puesta de sol en el Polo Sur"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://brr.fyi/posts/sunset",children:"Original"}),'.\nEn la estaci\xf3n del Polo Sur, el sol gira en un c\xedrculo casi perfecto en sentido contrario a las agujas del reloj alrededor del cielo, por lo que no hay diferencia entre "noche" y "d\xeda". Como resultado, la puesta de sol se extiende a lo largo de varias semanas, y la temperatura desciende r\xe1pidamente cuando el sol est\xe1 bajo en el cielo, normalmente hacia mediados de febrero. El post incluye fotograf\xedas de vistas de la puesta de sol desde varias direcciones, as\xed como un v\xeddeo para demostrar el extra\xf1o fen\xf3meno. La estaci\xf3n tambi\xe9n observa el "horario de verano", a pesar de que no hay diferencia visible entre las horas de un d\xeda determinado. El post detalla que la estaci\xf3n del Polo Sur sigue la hora de Nueva Zelanda y proporciona otros datos como las fases crepusculares y el primer avistamiento de estrellas de la temporada.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35500966",children:"Discussion Service"}),".\nUn post de Hacker News muestra hermosas fotos de la puesta de sol antes de una noche polar de 6 meses. Los comentarios hablan de la falta de luz solar, la regulaci\xf3n de la luz y la construcci\xf3n de instalaciones cient\xedficas. El experimento de solargraf\xeda fracasa. La construcci\xf3n de instalaciones en el Polo Sur es impresionante. Discusi\xf3n sobre el extra\xf1o fen\xf3meno del viaje circular del sol y su efecto en las condiciones de vida. La Ant\xe1rtida es inh\xf3spita y hay que competir por una posici\xf3n para ver la salida y la puesta del sol. Los comentaristas tambi\xe9n hablan de las dificultades para respirar en condiciones de fr\xedo extremo. El art\xedculo ofrece una interesante perspectiva de la vida y la investigaci\xf3n en la Ant\xe1rtida."]}),"\n",(0,n.jsx)(a.h2,{id:"un-periodista-holand\xe9s-cr\xedtico-con-china-objetivo-de-un-plan-de-intimidaci\xf3n",children:"Un periodista holand\xe9s cr\xedtico con China, objetivo de un plan de intimidaci\xf3n"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://nltimes.nl/2023/04/08/dutch-journalist-writes-critically-china-targeted-bizarre-intimidation-scheme",children:"Original"}),".\nMarije Vlaskamp, periodista holandesa cr\xedtica con China, es objeto desde el pasado oto\xf1o de una extra\xf1a trama de intimidaci\xf3n que incluye amenazas de bomba y mensajes exigi\xe9ndole que se retracte de un art\xedculo. Vlaskamp ha escrito anteriormente cr\xedticas sobre el Estado chino, centr\xe1ndose en la opresi\xf3n de los uigures y los disidentes chinos en los Pa\xedses Bajos. La embajada china en La Haya ha sido objeto de una amenaza de bomba en la que se mencionaba tanto a Vlaskamp como a Wang Jingyu, uno de los temas de sus art\xedculos. Aunque los agresores de Vlaskamp no intentan ocultar el origen chino de la amenaza, la embajada china ha negado su implicaci\xf3n en envalentonar a los atacantes."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501969",children:"Discussion Service"}),'.\nUn periodista holand\xe9s, objetivo de un plan de intimidaci\xf3n; los usuarios de Discussion Service debaten la injerencia china e instan a los gobiernos a hacer m\xe1s. Las comisar\xedas chinas operan en Holanda y otros pa\xedses, y es posible que los propios pa\xedses tengan que investigar las llamadas "acciones grises". Los cr\xedticos sostienen que las acciones de China violan la soberan\xeda, y algunos pol\xedticos han recibido amenazas por ello. Los usuarios de Discussion Service discuten el papel de China en los recientes incidentes con amenazas de bomba contra periodistas disidentes residentes en Estados Unidos; debates sobre el gobierno chino y sus acciones hacia los periodistas occidentales. ASML, una empresa holandesa, aparece en un contexto en el que China pretende adue\xf1arse de la electr\xf3nica de Occidente.']}),"\n",(0,n.jsx)(a.h2,{id:"las-instalaciones-de-usps-en-utah-no-hacen-m\xe1s-que-descifrar-la-escritura-a-mano",children:"Las instalaciones de USPS en Utah no hacen m\xe1s que descifrar la escritura a mano"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://kutv.com/news/eye-on-utah/what-happens-to-mail-with-band-handwriting-united-states-postal-service-letter-carrier-usps-mailwoman-mailman-cursive-taught-in-schools-unreadable-print-envelopes-undeliverable-packages-salt-lake-city-utah",children:"Original"}),".\nLa instalaci\xf3n de USPS en Utah est\xe1 especializada en descifrar la desordenada escritura manuscrita del correo. Esta instalaci\xf3n emplea a m\xe1s de 90 personas que clasifican el correo y utilizan tecnolog\xeda avanzada para procesarlo. La tecnolog\xeda utilizada puede incluso escanear y digitalizar direcciones manuscritas. Esta instalaci\xf3n muestra c\xf3mo la tecnolog\xeda est\xe1 evolucionando para realizar tareas tradicionales de forma innovadora."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35499641",children:"Discussion Service"}),".\nLa instalaci\xf3n de USPS en Utah est\xe1 especializada en descifrar la escritura manuscrita cursiva con un software proporcionado por Eagle y Siemens. El reconocimiento de la escritura manuscrita ha sido todo un reto para los trabajadores de correos, y sigue siendo necesaria la intervenci\xf3n humana. El debate en Hacker News aborda la evoluci\xf3n de la mano de obra y los salarios, la propiedad, las subvenciones gubernamentales y las ventajas de escribir en los libros. Se cree que la comunidad mormona de Salt Lake City ha contribuido a que el servicio cuente con un gran n\xfamero de lectores cualificados. Algunos sugieren que el USPS deber\xeda crear una aplicaci\xf3n m\xf3vil, mientras que otros expresan su preocupaci\xf3n por la violaci\xf3n de la intimidad con el uso de datos privados."]}),"\n",(0,n.jsx)(a.h2,{id:"apple-contin\xfaa-sus-esfuerzos-para-evitar-que-las-tiendas-minoristas-se-sindicalicen",children:"Apple contin\xfaa sus esfuerzos para evitar que las tiendas minoristas se sindicalicen"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.bloomberg.com/news/newsletters/2023-04-09/apple-aapl-continues-efforts-to-keep-retail-stores-from-unionizing-lg9gjdx2",children:"Original"}),".\nApple est\xe1 tratando de evitar que sus tiendas minoristas se sindicalicen, al tiempo que diversifica su producci\xf3n de productos y componentes fuera de China. La empresa ha sufrido recientemente recortes de plantilla y la salida de otro ejecutivo. El art\xedculo tambi\xe9n menciona el pr\xf3ximo lanzamiento de los auriculares de realidad mixta de Apple."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35503210",children:"Discussion Service"}),".\nApple acusada de t\xe1cticas antisindicales, incluida la retenci\xf3n de beneficios; cr\xedticas a las t\xe1cticas de negociaci\xf3n sindical. Debate sobre las complejidades de la sindicaci\xf3n y el impacto en los trabajadores. La encuesta Gallup muestra un creciente inter\xe9s por la sindicaci\xf3n, especialmente entre los trabajadores de primera l\xednea. Algunos critican los bajos salarios y la falta de prestaciones de los empleos en el comercio minorista, mientras que otros argumentan que los ascensos basados en la antig\xfcedad y los despidos podr\xedan afectar negativamente a las empresas."]}),"\n",(0,n.jsx)(a.h2,{id:"plrust-10-ahora-un-lenguaje-de-confianza-para-postgres",children:"PL/Rust 1.0: ahora un lenguaje de confianza para Postgres"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://tcdi.github.io/plrust/plrust.html",children:"Original"}),'.\nPL/Rust es un lenguaje procedimental cargable que permite escribir funciones PostgreSQL en Rust, proporcionando acceso a la Interfaz de Programaci\xf3n de Servidor de Postgres y tipos Rust seguros sobre la mayor\xeda de los tipos de datos incorporados en Postgres; las funciones PL/Rust son compiladas a c\xf3digo m\xe1quina nativo en lugar de ser interpretadas, proporcionando el mejor rendimiento. PL/Rust es ahora un lenguaje procedimental de confianza para Postgres en sistemas x86_64 y aarch64 si se cumplen los requisitos de compilaci\xf3n adecuados, lo que permite a PL/Rust vivir en un universo de Safe Rust; PL/Rust utiliza su propio controlador rustc para aplicar lints personalizados a la funci\xf3n LANGUAGE plrust de un usuario para aplicar ciertos modismos de c\xf3digo que saben que no tienen problemas de "I-Unsound". Por defecto, PL/Rust no realizar\xe1 compilaci\xf3n cruzada, pero debe ser instalado y habilitado a trav\xe9s de la configuraci\xf3n.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501065",children:"Discussion Service"}),".\nPL/Rust 1.0 conf\xeda ahora en Postgres como alternativa para las funciones de base de datos. Los proveedores de nube RDS y Supabase permiten la implementaci\xf3n de PL/Rust. Tiene un rendimiento excepcional pero sigue siendo vulnerable a problemas. Los disparadores de eventos y los bloques DO a\xfan no se han incorporado. Rust tiene acceso al ecosistema de desarrollo, tipos eficientes y mejor rendimiento. Puede limitar la optimizaci\xf3n para triggers computacionales."]}),"\n",(0,n.jsx)(a.h2,{id:"twitter-est\xe1-bloqueando-likes-y-retweets-que-mencionan-substack",children:"Twitter Est\xe1 Bloqueando Likes y Retweets que Mencionan Substack"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://flipboard.social/@Flipboard/110161362001035875",children:"Original"}),".\nN/A."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35502684",children:"Discussion Service"}),'.\nTwitter bloquea los likes/retweets que mencionan a Substack, provocando el efecto Streisand. Elon Musk acusa a Substack de haber escarbado en la base de datos de Twitter, los expertos consideran que la afirmaci\xf3n carece de sentido. Substack niega el uso indebido de las API de Twitter. Cr\xedticas a los resultados de b\xfasqueda, las prohibiciones y las pol\xedticas de uso de API de Twitter. Preocupaci\xf3n por la calidad de la funci\xf3n de noticias de Substack. Evoluci\xf3n de la competencia entre Twitter y Substack, exploraci\xf3n de protocolos de microblogging alternativos. Resistencia a convertir el asunto en un espect\xe1culo, llamamiento a la responsabilidad de los l\xedderes. Contin\xfaan los debates sobre el abuso de la API y el supuesto "scraping" de contenidos de Twitter por parte de Substack. Precauci\xf3n ante la situaci\xf3n de los empleados despedidos de Substack.']}),"\n",(0,n.jsx)(a.h2,{id:"z-library-permitir\xe1-a-los-usuarios-compartir-libros-f\xedsicos",children:"Z-Library permitir\xe1 a los usuarios compartir libros f\xedsicos"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://torrentfreak.com/z-library-plans-to-let-users-share-physical-books-through-z-points-230408/",children:"Original"}),'.\nZ-Library, el mayor repositorio de libros pirateados, est\xe1 ampliando sus servicios para incluir un mercado de libros f\xedsicos compartidos, con millones de usuarios que podr\xe1n recoger libros de bolsillo en "Z-Points" dedicados en todo el mundo. Tiene previsto organizar "puntos de recogida y almacenamiento" de libros que "ser\xe1n el enlace entre quienes comparten sus libros y quienes los necesitan", lo que requerir\xe1 un espacio de almacenamiento y un esfuerzo organizativo considerables, por lo que los centros de cumplimiento y los servicios log\xedsticos de terceros son bienvenidos. Un anuncio publicado en el sitio parece ir en serio, ya que la gente sugiere Vietnam, Brasil, Portugal, Colombia, Ir\xe1n, Uzbekist\xe1n, Nigeria, Espa\xf1a, India, Argentina, Egipto, Francia, Etiop\xeda, China y Ghana como ubicaciones ideales de los Z-Points, y el sitio est\xe1 recibiendo comentarios para mejorar su servicio.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35499065",children:"Discussion Service"}),".\nZ-Library permitir\xe1 a los usuarios compartir libros f\xedsicos, pero los editores podr\xedan demandar a la biblioteca; algunos sugieren escanear libros, cambiar las leyes de derechos de autor o incentivar el escaneo de libros. Algunos debaten sobre la viabilidad y el impacto en las editoriales del lanzamiento de un mercado de libros compartidos en el mundo real. Los modelos de concesi\xf3n de licencias de libros electr\xf3nicos tienen consecuencias desafortunadas, que conducen a la pirater\xeda como forma de protesta. Las bibliotecas privadas de socios son anteriores a las bibliotecas p\xfablicas y a menudo se prestan."]}),"\n",(0,n.jsx)(a.h2,{id:"perseus---alternativa-a-nextjs-en-rust",children:"Perseus - Alternativa a NextJS en Rust"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://framesurge.sh/perseus/en-US/",children:"Original"}),".\nPerseus es un framework en Rust para aplicaciones web modernas que genera estado bajo demanda y lo pasa a Sycamore, con I18n basado en Fluent a\xf1adido para funcionalidad multiling\xfce, plugins para personalizaci\xf3n, todo en WebAssembly para alto rendimiento, y exportable/servido est\xe1ticamente, f\xe1cil de instalar, y amigable."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35500528",children:"Discussion Service"}),".\nLos usuarios discuten sobre Perseus, una alternativa basada en Rust a NextJS, y algunos prefieren JS para el desarrollo front-end debido a las herramientas de Rust. A pesar de ello, las incursiones de Rust en los niveles inferiores de la pila JS sugieren un potencial en la incorporaci\xf3n de JS/TS en frameworks Rust como Perseus. Algunos usuarios consideran que Rust es m\xe1s adecuado para la programaci\xf3n de bajo nivel y otros que Go es m\xe1s apropiado para el desarrollo web. El valor de un lenguaje de programaci\xf3n depende de d\xf3nde se viva y se quiera trabajar. El lanzamiento de Perseus atrae la atenci\xf3n de los expertos en tecnolog\xeda como posible alternativa m\xe1s r\xe1pida a Svelte, pero se enfrenta a cr\xedticas por ser dif\xedcil de utilizar en el mundo real."]}),"\n",(0,n.jsx)(a.h2,{id:"a-baby-gpt",children:"A Baby GPT"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://twitter.com/karpathy/status/1645115622517542913",children:"Original"}),".\nN/A."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35506069",children:"Discussion Service"}),".\nUn usuario de Discussion Service propone utilizar expresiones regulares binarias para las relaciones ling\xfc\xedsticas, mientras que otro aboga por el significado y la intenci\xf3n. El creador de la GPT para beb\xe9s la compara con la cadena de Markov. Un experto recomienda mejores herramientas matem\xe1ticas. Un usuario de Discussion Service pregunta por las implicaciones para el p\xfablico en general. No hay novedades tecnol\xf3gicas destacables."]}),"\n",(0,n.jsx)(a.h2,{id:"dos-tipos-de-ingenieros-de-software",children:"Dos tipos de ingenieros de software"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://registerspill.thorstenball.com/p/two-types-of-software-engineers",children:"Original"}),".\nEl art\xedculo discute dos tipos de ingenieros de software: El tipo 1, que asume que un problema es f\xe1cil si no es t\xe9cnico, y el tipo 2, que asume que es dif\xedcil porque implica a personas. El tipo 1 cree en la ingenier\xeda con E may\xfascula, mientras que el tipo 2 se centra en las personas y considera que los problemas de ingenier\xeda implican a personas. Aunque el Tipo 1 es el m\xe1s com\xfan, los ingenieros de Tipo 2 entienden que la ingenier\xeda implica caos y complejidad y pretenden construir a pesar de estos retos. El art\xedculo incluye algunos ejemplos para ilustrar las diferencias, pero el autor a\xfan no ha definido ni trazado con precisi\xf3n la l\xednea divisoria entre ambos tipos."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35503784",children:"Discussion Service"}),".\nDebate sobre los dos tipos de ingenieros de software, incluido el Tipo 3, y la importancia de entender la gesti\xf3n de productos. Debate sobre el equilibrio entre innovaci\xf3n y estabilidad, y la necesidad de una documentaci\xf3n adecuada. Dicotom\xeda entre confiar en las personas y aplicar soluciones automatizadas en la ingenier\xeda de software. Importancia de alinear a todos en torno a objetivos comunes y de comprender las necesidades empresariales m\xe1s amplias. Cuestionamiento de la categorizaci\xf3n de los ingenieros de software, con \xe9nfasis en la b\xfasqueda de la causa ra\xedz de los problemas. El art\xedculo da que pensar."]}),"\n",(0,n.jsx)(a.h2,{id:"programaci\xf3n-avanzada-en-linux-2001",children:"Programaci\xf3n avanzada en Linux (2001)"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://mentorembedded.github.io/advancedlinuxprogramming/",children:"Original"}),".\n'Advanced Linux Programming' de CodeSourceryLLC es un libro que ayuda a los desarrolladores de GNU/Linux a crear software con caracter\xedsticas f\xe1ciles de usar, capacidades avanzadas como multi-threading, comunicaci\xf3n entre procesos, e interacci\xf3n con dispositivos hardware, y mejora general del programa. Adem\xe1s, este libro ense\xf1a a los desarrolladores c\xf3mo trabajar dentro del entorno del sistema GNU/Linux, incluyendo sus limitaciones, convenciones y capacidades \xfanicas. Este libro est\xe1 disponible para su descarga bajo la Licencia de Publicaci\xf3n Abierta, Versi\xf3n 1, e incluye acceso a ejemplos de c\xf3digo cubiertos por la Licencia P\xfablica General de GNU. Erratas y traducciones del libro est\xe1n disponibles."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35500197",children:"Discussion Service"}),'.\nLos usuarios de Hacker News discuten la relevancia del libro de 2001, "Advanced Linux Programming" en 2021. Algunos usuarios sugieren actualizar las secciones obsoletas. A pesar de ser un libro para principiantes, sigue siendo un recurso \xfatil para el desarrollo de API Linux. La aplicaci\xf3n de descarga Aria2 sirve como alternativa a los l\xedmites de velocidad del servidor.']}),"\n",(0,n.jsx)(a.h2,{id:"un-cern-para-la-ia-a-gran-escala-de-c\xf3digo-abierto",children:"Un CERN para la IA a gran escala de c\xf3digo abierto"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.openpetition.eu/petition/online/securing-our-digital-future-a-cern-for-open-source-large-scale-ai-research-and-its-safety",children:"Original"}),".\nLAION e.V. ha lanzado una petici\xf3n a favor de un centro internacional de investigaci\xf3n en supercomputaci\xf3n para la IA, financiado con fondos p\xfablicos y de c\xf3digo abierto, similar al CERN, para democratizar la investigaci\xf3n en IA y promover la investigaci\xf3n en seguridad y protecci\xf3n. La plataforma openPetition pretende reforzar la participaci\xf3n ciudadana y apoyar las peticiones de cambio. La iniciativa pretende proteger los principios democr\xe1ticos para que no se vean socavados por unas pocas grandes empresas. Un usuario de Discussion Service se\xf1al\xf3 que el 19% de los partidarios proceden de laion.ai, mientras que el 64% son desconocidos. Se anima a los ciudadanos a donar para apoyar la petici\xf3n que ha ganado tracci\xf3n en Hacker News."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501845",children:"Discussion Service"}),".\nUn art\xedculo de openpetition.eu destaca la necesidad en Europa de una iniciativa de c\xf3digo abierto similar a la del CERN para promover la colaboraci\xf3n entre investigadores, acad\xe9micos y empresarios de IA. La colaboraci\xf3n es necesaria para llevar a cabo el procesamiento de big data con grandes inversiones de capital. Los proyectos de c\xf3digo abierto son necesarios para retener a los investigadores de IA y beneficiar a la sociedad m\xe1s que a los accionistas de las empresas. El \xe9xito del CERN lo convierte en un modelo atractivo, aunque algunos sugieren que el mercado ofrece incentivos adecuados. La naturaleza interdisciplinar de la IA exige considerar cuestiones interconectadas."]}),"\n",(0,n.jsx)(a.h2,{id:"permafrost-engine---un-motor-de-juego-opengl-rts-escrito-en-c",children:"Permafrost engine - Un motor de juego OpenGL RTS escrito en C"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://github.com/eduard-permyakov/permafrost-engine",children:"Original"}),".\nPermafrost Engine es un motor de juegos de estrategia en tiempo real OpenGL 3.3 escrito en C, hecho a imagen de los viejos cl\xe1sicos pero incorporando algunas ideas modernas. EVERGLORY es el juego estrella desarrollado con Permafrost Engine, que muestra las capacidades del motor con experiencia de juego de primera mano. El resumen del motor incluye una lista de caracter\xedsticas OpenGL y Python, mec\xe1nicas RTS y capacidades multiplataforma. La licencia de Permafrost Engine es GPLv3, con una excepci\xf3n especial para enlaces. Se proporcionan instrucciones de construcci\xf3n para Linux y Windows. Los usuarios interesados tienen a su disposici\xf3n un devlog y un correo electr\xf3nico para preguntas y comentarios sobre el proyecto o el c\xf3digo fuente."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35504053",children:"Discussion Service"}),".\nEl motor de c\xf3digo abierto Permafrost llama la atenci\xf3n en Discussion Service para un nuevo juego de estrategia en tiempo real de c\xf3digo abierto. Se critica la claridad de las fuentes del juego Everglory. Se solicita una comparaci\xf3n con otros motores RTS. Es importante que los desarrolladores prueben en pantallas port\xe1tiles. Esperanza para el renacimiento del g\xe9nero RTS. Los usuarios hablan de motores RTS de c\xf3digo abierto y de los lenguajes utilizados. Menci\xf3n de otra implementaci\xf3n del motor Frostbite de c\xf3digo abierto."]}),"\n",(0,n.jsx)(a.h2,{id:"cierre-de-una-conexi\xf3n-ssh-obsoleta",children:"Cierre de una conexi\xf3n SSH obsoleta."}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://davidisaksson.dev/posts/closing-stale-ssh-connections/",children:"Original"}),".\nEl post discute c\xf3mo cerrar una sesi\xf3n SSH antigua, afirmando que mientras la primera soluci\xf3n podr\xeda ser cerrar el emulador de terminal, hay una mejor manera de utilizar las secuencias de escape SSH incorporadas. El post explica c\xf3mo el prefijo tilde (",(0,n.jsx)(a.del,{children:") seguido de un comando puede activar m\xfaltiples comandos ocultos en clientes SSH, incluyendo el comando 'terminar sesi\xf3n' ("}),".). El post se\xf1ala que se debe prestar atenci\xf3n al hecho de que se requiere una nueva l\xednea precedente, y ofrece una peque\xf1a nota para las personas que utilizan un teclado con una disposici\xf3n n\xf3rdica para escribir el car\xe1cter tilde. El post termina con una discusi\xf3n sobre qu\xe9 hacer despu\xe9s de usar la secuencia de escape 'terminar sesi\xf3n'."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35504402",children:"Discussion Service"}),".\nUn usuario de Discussion Service da un consejo sobre SSH. Otro se\xf1ala un problema de dise\xf1o pero proporciona una soluci\xf3n. Se sugiere configurar EscapeChar. Discusi\xf3n sobre SSH manpage, saltando hosts, y conexiones SSH. Se desea una sesi\xf3n SSH pegajosa. Se recomienda Autossh para auto-attach, y Mosh para cambiar el reenv\xedo de puertos. Detalles de encriptaci\xf3n y consejos adicionales. Se desaconseja el uso de Alpine Linux."]}),"\n",(0,n.jsx)(a.h2,{id:"flatcar-container-linux",children:"Flatcar Container Linux"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.flatcar.org/",children:"Original"}),".\nFlatcar Container Linux es una distribuci\xf3n Linux comunitaria que est\xe1 dise\xf1ada para cargas de trabajo de contenedores con alta seguridad y bajo mantenimiento. La imagen del sistema operativo s\xf3lo incluye las herramientas necesarias para ejecutar contenedores sin gestor de paquetes ni deriva de configuraci\xf3n. El sistema de archivos inmutable y las actualizaciones at\xf3micas automatizadas proporcionan una base s\xf3lida para la seguridad de la infraestructura. Las funciones de seguridad integradas de Flatcar Container Linux y su reducida superficie de ataque simplifican la gesti\xf3n del SO. Incluye herramientas para gestionar infraestructuras a gran escala y es compatible con iniciativas globales. Las actualizaciones at\xf3micas automatizadas garantizan la ejecuci\xf3n de la versi\xf3n m\xe1s estable, segura y actualizada de Flatcar. Es un sustituto directo de CoreOS Container Linux."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35503928",children:"Discussion Service"}),".\nFlatcar Container Linux de Microsoft se actualiza y contin\xfaa tras su adquisici\xf3n, proporcionando una alternativa a CloudInit. El enfoque de infraestructura inmutable gana popularidad a pesar de los problemas t\xe9cnicos de Ignition. Los desarrolladores de Flatcar Linux sugieren una actualizaci\xf3n amistosa. Los usuarios de Discussion Service discuten la adici\xf3n de contenedores y sugieren un firmware UEFI para un mejor rendimiento."]}),"\n",(0,n.jsx)(a.h2,{id:"microsoft--jarvis-un-sistema-para-conectar-llms-con-la-comunidad-ml",children:"Microsoft / JARVIS: un sistema para conectar LLMs con la comunidad ML"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://github.com/microsoft/JARVIS",children:"Original"}),".\nMicrosoft y Hugging Face han presentado el proyecto JARVIS de Labs, un asistente de IA para conectar modelos ling\xfc\xedsticos y de aprendizaje autom\xe1tico. JARVIS utiliza un gran modelo ling\xfc\xedstico (LLM) para comprender y analizar las peticiones y, a continuaci\xf3n, recurre a una selecci\xf3n de numerosos modelos expertos para ejecutar la tarea requerida. Consta de cuatro etapas: planificaci\xf3n de tareas, selecci\xf3n de modelos, ejecuci\xf3n de tareas y generaci\xf3n de respuestas. El usuario puede disfrutar de una experiencia ligera con JARVIS sin desplegar los modelos localmente activando su modo CLI o la p\xe1gina web, que muestra una interfaz de f\xe1cil manejo que se comunica con JARVIS."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35500472",children:"Discussion Service"}),".\nMicrosoft lanza JARVIS para conectar los LLM con la comunidad de ML mediante enfoques basados en reglas y aprendizaje autom\xe1tico. Algunos especulan sobre si los agentes aut\xf3nomos de IA pueden cometer fraudes o estafas, aunque los lectores est\xe1n sobre todo entusiasmados. Jarvis genera texto e im\xe1genes bas\xe1ndose en los modelos elegidos por los LLM, pero algunos plantean dudas sobre cuestiones de marcas registradas y escuchas."]}),"\n",(0,n.jsx)(a.h2,{id:"un-tokamak-esf\xe9rico-alcanza-temperaturas-de-plasma-cruciales",children:"Un tokamak esf\xe9rico alcanza temperaturas de plasma cruciales"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.eetimes.com/spherical-tokamak-achieves-crucial-plasma-temperatures/",children:"Original"}),".\nEl tokamak esf\xe9rico de Tokamak Energy alcanz\xf3 temperaturas i\xf3nicas de m\xe1s de 100 millones de grados Kelvin, un paso decisivo en el desarrollo de la tecnolog\xeda de la energ\xeda de fusi\xf3n. El peque\xf1o tama\xf1o, la estabilidad del plasma y las propiedades de confinamiento magn\xe9tico de los tokamaks esf\xe9ricos los convierten en una opci\xf3n atractiva para la producci\xf3n comercial de energ\xeda de fusi\xf3n. Steven McNamara, director cient\xedfico de Tokamak Energy, cree que la empresa puede poner la energ\xeda de fusi\xf3n en red en un plazo de 10 a\xf1os, complementando otras fuentes de energ\xeda renovables. El avance utiliza la dispersi\xf3n de Thomson para medir la temperatura y la densidad en m\xfaltiples puntos, allanando el camino para centrales de fusi\xf3n comerciales de bajo coste y desplegables. La tecnolog\xeda tambi\xe9n tiene aplicaciones potenciales en la aviaci\xf3n sostenible y la producci\xf3n de combustible de hidr\xf3geno."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35505342",children:"Discussion Service"}),".\nUn tokamak esf\xe9rico alcanza temperaturas de plasma cruciales. Algunos usuarios discuten cuestiones estructurales, uno recomienda un podcast sobre energ\xeda de fusi\xf3n. El art\xedculo explica la necesidad de un intercambiador de calor y los costes reducidos del nuevo dise\xf1o. Se debate la viabilidad de la fusi\xf3n comercial. La duplicaci\xf3n de la fuerza del im\xe1n en pruebas a peque\xf1a escala avanza el progreso. Se se\xf1alan las ventajas de la fusi\xf3n sobre la fisi\xf3n en cuanto a residuos y seguridad. Los tokamaks esf\xe9ricos son una aplicaci\xf3n de vanguardia. El hito alcanzado a\xfan no es \xfatil, pero se avanza en la fuerza del im\xe1n."]}),"\n",(0,n.jsx)(a.h2,{id:"los-primeros-huevos-de-pascua-del-juego-fueron-un-acto-de-rebeld\xeda-empresarial",children:"Los primeros 'huevos de Pascua' del juego fueron un acto de rebeld\xeda empresarial"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://thehustle.co/the-first-easter-eggs-were-an-act-of-corporate-rebellion/",children:"Original"}),'.\nLos primeros huevos de Pascua en los videojuegos fueron el resultado de que a los dise\xf1adores se les negara el cr\xe9dito por su trabajo, lo que dio lugar a mensajes ocultos en los juegos. El primer huevo de Pascua se encontr\xf3 en el juego de Atari de 1980 "Adventure", creado por Warren Robinett. La tradici\xf3n de los mensajes ocultos continu\xf3 en los juegos arcade de los a\xf1os 70 en busca de reconocimiento e individualidad. El huevo de Pascua de Robinett elev\xf3 su estatus, y pas\xf3 a desarrollar un exitoso negocio de software. El Tech Times informa de varias cookies utilizadas por las empresas para rastrear el comportamiento en l\xednea de los usuarios y personalizar los anuncios, pero a\xfan no se han clasificado.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35503260",children:"Discussion Service"}),".\nUn post de Hacker News sobre la rebeli\xf3n corporativa a trav\xe9s de los huevos de Pascua presenta an\xe9cdotas y pol\xedticas corporativas actuales. El inter\xe9s de los lectores puede despertar por la relevancia hist\xf3rica y la evoluci\xf3n del papel del huevo de Pascua. Los huevos de Pascua actuales expresan orgullo corporativo, no insubordinaci\xf3n. Las revisiones del c\xf3digo evitan los huevos de Pascua. Las antiguas empresas tecnol\xf3gicas suelen depender de MBA reci\xe9n nombrados. Warren Robinett es elogiado por Adventure game. El miembro de U2 y el fan de Atari tienen nombres diferentes."]}),"\n",(0,n.jsx)(a.h2,{id:"errores-modulares-en-rust",children:"Errores modulares en Rust"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://sabrinajewson.org/blog/errors",children:"Original"}),".\nEl art\xedculo discute la importancia del manejo modular de errores e introduce el principio de que los tipos de error est\xe9n cerca de su unidad de falibilidad, usando una biblioteca hipot\xe9tica de Rust como ejemplo. Se esbozan problemas con mensajes de error poco \xfatiles, inextensibilidad y dificultad para emparejar errores, y se sugieren soluciones como el m\xe9todo .source() y una mejor construcci\xf3n del tipo de error. El tipo de error de la biblioteca de ejemplo se divide en tres tipos distintos con un buen rastreo y una correspondencia de errores precisa, y los errores de E/S se explican mediante un dise\xf1o de tipo de error m\xe1s estructurado. El art\xedculo enfatiza la importancia de una buena trazabilidad, extensibilidad, inspeccionabilidad, estabilidad y modularidad en el manejo de errores, y sugiere que vale la pena aprender a manejar bien los errores."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35502874",children:"Discussion Service"}),".\nLos mensajes de error de Rust son populares, pero se necesitan tipos de error variados. SNAFU permite producir trazas \xfanicas. Errores distintos reducen la proliferaci\xf3n y facilitan el manejo pero cuidado con soportar APIs p\xfablicas. El registro y la terminaci\xf3n no deber\xedan ser el enfoque principal para depurar bibliotecas. Son preferibles los errores granulares u opacos con descripciones. Las excepciones comprobadas en Java son alabadas. El defecto fatal de Java es no tener tipos algebraicos."]}),"\n",(0,n.jsx)(a.h2,{id:"regla-68-95-997",children:"Regla 68-95-99.7"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://en.wikipedia.org/wiki/68%E2%80%9395%E2%80%9399.7_rule",children:"Original"}),".\nLa regla 68-95-99.7 es una aproximaci\xf3n estad\xedstica que estima el porcentaje de valores dentro de una desviaci\xf3n est\xe1ndar de la media en una distribuci\xf3n normal. La regla establece que aproximadamente el 68%, el 95% y el 99,7% se encuentran dentro de una, dos y tres desviaciones est\xe1ndar respectivamente. Esta regla tiene m\xfaltiples usos en distintos campos, como el control de calidad y el an\xe1lisis de datos. Es una forma r\xe1pida de obtener una estimaci\xf3n aproximada de la probabilidad de una poblaci\xf3n que se supone normal. La f\xf3rmula puede aplicarse a distintas distribuciones y puede ayudar a identificar valores at\xedpicos en el an\xe1lisis de datos."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501780",children:"Discussion Service"}),".\nEn los comentarios de Discussion Service se discuten las limitaciones de la regla 68-95-99,7 en el an\xe1lisis de datos. Se menciona el trabajo de Nassim Nicholas Taleb y la desigualdad de Chebyshev. Tangents on financial trading & history of US options market. Los usuarios expertos afirman que las puntuaciones altas de CI no son fiables y que la escala es arbitraria."]}),"\n",(0,n.jsx)(a.h2,{id:"unicodeplots",children:"UnicodePlots"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://github.com/JuliaPlots/UnicodePlots.jl",children:"Original"}),".\nLa biblioteca UnicodePlots es una herramienta de trazado de alto nivel para su uso en el REPL de Julia que incluye gr\xe1ficos de dispersi\xf3n, gr\xe1ficos de l\xedneas y mapas de calor. Tambi\xe9n es compatible con las cantidades f\xedsicas de Unitful.jl y los intervalos de IntervalSets.jl, permite la personalizaci\xf3n de las caracter\xedsticas del trazado, como la altura y la anchura del trazado y los ejes de trazado inverso/inverso, y permite guardar los trazados como PNG o TXT."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35505591",children:"Discussion Service"}),".\nUnicodePlots basado en Julia muestra gr\xe1ficos e histogramas en el terminal para visualizaciones r\xe1pidas en servidores remotos. Responde a una necesidad de visualizaci\xf3n r\xe1pida de datos en el terminal, sin instalar una pila de gr\xe1ficos completa. UnicodePlots se copia sobre todo en un puerto Ruby, y una versi\xf3n Python que es compatible con Matplotlib. Actualmente hay una tendencia hacia las interfaces de usuario de texto, creando una divisi\xf3n entre Electron para aplicaciones de usuario final y TUI para herramientas port\xe1tiles. Tiene una cobertura de c\xf3digo del 100%, admite histogramas comparativos y permite a los usuarios copiar y pegar datos directamente en comentarios o descripciones. Aunque no se trata de una tecnolog\xeda totalmente nueva, UnicodePlots es una herramienta \xfatil para quienes necesitan evaluar datos r\xe1pidamente."]}),"\n",(0,n.jsx)(a.h2,{id:"digital-collectibles-on-instagram-is-winding-down",children:"Digital collectibles on Instagram is winding down"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://help.instagram.com/1824155514623095",children:"Original"}),".\nA partir del 11 de abril de 2023, Instagram dejar\xe1 de dar soporte a los coleccionables digitales, lo que afectar\xe1 a la creaci\xf3n de nuevas publicaciones de coleccionables digitales, a la visibilidad de los monederos digitales y a la accesibilidad de la informaci\xf3n de blockchain. La eliminaci\xf3n de los datos de los coleccionables digitales se har\xe1 de acuerdo con la Pol\xedtica de Privacidad y las Condiciones de Uso de los Coleccionables Digitales de Instagram, pero los usuarios podr\xe1n presentar una solicitud para descargar su informaci\xf3n antes de la fecha l\xedmite. El contenido de los monederos digitales de terceros no se ver\xe1 afectado."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501074",children:"Discussion Service"}),'.\nLos coleccionables digitales de Instagram pierden fuelle, pero los creyentes de web3 no se amilanan. El espacio NFT necesita abordar las normas de propiedad y la adopci\xf3n comercial. Los avatares de Reddit se venden bien, aunque los NFT poligonales se perciben como menos valiosos. El invierno es bienvenido para que los constructores construyan infraestructuras y para que las empresas tradicionales aprendan sobre las redes descentralizadas. El \xe9xito de las tarjetas Pokemon y los avatares de Reddit se compara con el concepto de escasez. La expresi\xf3n "Web3" puede ser prematura y los estafadores y los constructores est\xe1n en bandos diferentes. Hay escepticismo y preocupaci\xf3n por el bombo de las NFT, los riesgos de inversi\xf3n y la salud mental. Se discute la implicaci\xf3n de los cultos en las industrias, las criptomonedas y los riesgos de la IA. Se debate la utilidad de ChatGPT, y los usuarios se centran en ideas frescas sin lenguaje pol\xedtico o religioso. Se discute el contexto de la tecnolog\xeda avanzada en su relaci\xf3n con la comunicaci\xf3n y la sincronizaci\xf3n con la Tierra, con diversas opiniones sobre el valor de la NFT y su impacto en la sociedad.']}),"\n",(0,n.jsx)(a.h2,{id:"la-sentencia-que-amenaza-el-futuro-de-las-bibliotecas",children:"La sentencia que amenaza el futuro de las bibliotecas"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.theatlantic.com/ideas/archive/2023/04/internet-archive-libraries-federal-court-ruling/673615/",children:"Original"}),'.\nUna sentencia de un tribunal federal que dictamina que el pr\xe9stamo digital controlado (CDL) viola la ley de derechos de autor podr\xeda tener consecuencias desastrosas para las bibliotecas, como tener que elegir entre adquirir costosas licencias de libros electr\xf3nicos a las editoriales o ampliar sus colecciones; el Archivo de Internet (AI), una organizaci\xf3n sin \xe1nimo de lucro que presta copias digitales de los millones de libros que ha recopilado y digitalizado, ha estado en el centro de una demanda de varias editoriales de libros que lo demandaron en 2020 alegando una violaci\xf3n de los derechos de autor; y fue este modelo de pr\xe9stamo de CDL contra el que fall\xf3 el tribunal el mes pasado, que podr\xeda tener "un poder injusto sobre el futuro de los libros y las bibliotecas por igual", seg\xfan la abogada Corynne McSherry, de la Electronic Frontier Foundation, que representa a la AI en su recurso sobre la sentencia.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35502238",children:"Discussion Service"}),".\nLa sentencia judicial sobre el pr\xe9stamo digital controlado y las leyes de derechos de autor ha suscitado debates, con sugerencias de acortar la duraci\xf3n de los derechos de autor para evitar la p\xe9rdida de conocimientos; algunos sugieren que los beneficios de los editores no deber\xedan ser el problema a la hora de prestar material CDL. Las bibliotecas se han adaptado para convertirse en centros p\xfablicos de ocio, y el acceso p\xfablico a los recursos es fundamental; los bibliotecarios recurren a la opini\xf3n de expertos para equilibrar la popularidad de la circulaci\xf3n, el valor del libro y la misi\xf3n de la biblioteca a la hora de descartar libros. Las demandas de los editores contra la distribuci\xf3n digital ilimitada libre de derechos de autor de Internet Archive comprometen los ingresos de los escritores, y el pr\xe9stamo digital controlado podr\xeda poner en peligro la protecci\xf3n de las leyes de derechos de autor. La intersecci\xf3n de la propiedad digital y f\xedsica sigue siendo un tema de debate; las discusiones ofrecen perspectivas \xfanicas sobre el asunto en cuesti\xf3n."]}),"\n",(0,n.jsx)(a.h2,{id:"do-kwon-convirti\xf3-fondos-il\xedcitos-de-luna-a-bitcoin",children:"Do Kwon convirti\xf3 fondos il\xedcitos de LUNA a Bitcoin"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://cointelegraph.com/news/do-kwon-converted-stolen-funds-from-luna-to-bitcoin-s-korean-prosecutors",children:"Original"}),".\nLos fiscales surcoreanos han identificado activos il\xedcitos por valor de casi 314,2 millones de d\xf3lares vinculados al cofundador de Terraform Labs, Do Kwon, y sus socios, de los cuales Kwon por s\xed solo est\xe1 relacionado con unos 69 millones de d\xf3lares. Los fiscales se han puesto en contacto con Binance para que detenga cualquier solicitud de retirada de fondos asociada a Kwon. Al parecer, Kwon convirti\xf3 la mayor parte de los fondos il\xedcitos, que rondan los 414.500 millones de wones, en Bitcoin, y ninguno de los activos relacionados con \xe9l es recuperable ni est\xe1 bajo la jurisdicci\xf3n de las autoridades surcoreanas. Terra fue un ecosistema de criptomonedas que se derrumb\xf3 en mayo de 2022, en el que el ex CEO Kwon fue acusado de desviar Bitcoin por valor de casi 100 millones de d\xf3lares despu\xe9s del colapso."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35499996",children:"Discussion Service"}),".\nLos datos en cadena muestran la conversi\xf3n de Bitcoin de fondos fraudulentos de LUNA por parte de Do Kwon de Terraform Labs. Expone las limitaciones del seguimiento del fraude a trav\xe9s de los bancos tradicionales. Los usuarios de Discussion Service debaten sobre herramientas de privacidad y honestidad en el espacio criptogr\xe1fico. Debate sobre si la inteligencia evolucion\xf3 para competir o para cooperar, con algunos defendiendo lo segundo. La competencia y la depredaci\xf3n impulsan la competencia, pero la tendencia general es seguir debatiendo los papeles en la evoluci\xf3n de la inteligencia."]}),"\n",(0,n.jsx)(a.h2,{id:"entrevista-con-andrew-kelley-creador-de-zig-2021",children:"Entrevista con Andrew Kelley (creador de Zig) (2021)"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://corecursive.com/067-zig-with-andrew-kelley/",children:"Original"}),".\nAndrew Kelley habla de sus experiencias en el desarrollo del lenguaje de programaci\xf3n Zig, de los retos de compaginar un trabajo a tiempo completo con el trabajo de c\xf3digo abierto, de la importancia de negociar la titularidad de la propiedad intelectual y de las cuestiones morales que rodean a la bifurcaci\xf3n comercial en la comunidad de c\xf3digo abierto. Zig es un lenguaje de programaci\xf3n sin \xe1nimo de lucro cuyo objetivo es mejorar la seguridad de la memoria y reducir la sobrecarga de informaci\xf3n para los usuarios. Kelley prev\xe9 que Zig se convierta en el lenguaje preferido para sistemas operativos y libros de texto, lo que mejorar\xe1 el rendimiento de las aplicaciones, el uso de la memoria y la estabilidad. Tech Times tambi\xe9n informa sobre varios videocursos de programaci\xf3n disponibles en Internet."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35502151",children:"Discussion Service"}),".\nLa entrevista de Corecursive con Andrew Kelley, creador de Zig, anima a los oyentes a descargar todos los podcasts anteriores del sitio web, y habla de proyectos de financiaci\xf3n colectiva y consejos personales en comentarios aparte. Un oyente aprecia el ambiente amistoso del canal #chicken scheme. Otro destaca la transparencia de Andrew Kelley en un incidente de Zig bifurcado, pero un usuario responde negativamente a su interacci\xf3n con Kelley. En general, los oyentes disfrutan de la cobertura de la entrevista sobre Zig y la historia tecnol\xf3gica de SQLite."]}),"\n",(0,n.jsx)(a.h2,{id:"supavisor---un-pooler-de-conexiones-postgres-escrito-en-elixir",children:"Supavisor - un pooler de conexiones Postgres escrito en Elixir"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://github.com/supabase/supavisor",children:"Original"}),".\nSupavisor es un pooler de conexiones Postgres que puede proxy millones de Postgres conexiones de cliente final en un estado de la piscina de Postgres conexiones de base de datos nativa a trav\xe9s de una arquitectura escalable, nativa de la nube. Este sistema simplifica la gesti\xf3n de cl\xfasteres Postgres para los administradores de bases de datos, proporcionando una f\xe1cil configuraci\xf3n de cl\xfasteres Postgres de alta disponibilidad, al tiempo que es eficiente en recursos, escalable, multi-tenant y nativo de la nube. Ya hay benchmarks y pruebas de carga disponibles, que muestran que puede manejar un mill\xf3n de conexiones Postgres en un cl\xfaster y puede absorber millones de conexiones, por lo que es una gran opci\xf3n para los desarrolladores que se conectan a Postgres desde entornos Serverless. El trabajo futuro incluye balanceo de carga, agrupaci\xf3n de sesiones, gesti\xf3n de alta disponibilidad de Postgres y APIs como Postgres binary, HTTPS y mucho m\xe1s. Jos\xe9 Valim y el equipo de Dashbit ayudaron a informar las decisiones de dise\xf1o de Supavisor, y est\xe1 inspirado en productos como PgBouncer, Amazon RDS Proxy, Google Cloud SQL Proxy, y m\xe1s."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501718",children:"Discussion Service"}),".\nEl CEO de Supabase presenta Supavisor, un pooler de conexiones Postgres construido con Elixir, destacando su similitud con Pgbouncer y dise\xf1ado para multi-tenancy. Los benchmarks de Supavisor indican que puede manejar un alto rendimiento mientras consume 7.8G RAM y ~50% CPU en una m\xe1quina de 64vCPU. Supabase planea tener Supavisor frente a todas sus bases de datos, escalando la computaci\xf3n con cero tiempo de inactividad. Los usuarios de Discussion Service solicitan la adici\xf3n de sentencias preparadas en el modo de agrupaci\xf3n de transacciones y la sugerencia de utilizar Nimble_pool en lugar de Poolboy, al tiempo que elogian el soporte de concurrencia y la naturaleza tolerante a fallos de Elixir. Un usuario de Discussion Service comparte su experiencia de trabajo con Pgbouncer en 4 m\xe1quinas vCPU y otro habla de su pool de Pgbouncers comunes que se dirigen a varias instancias PostgreSQL utilizando el proxy Cloud SQL de Google."]}),"\n",(0,n.jsx)(a.h2,{id:"nuevas-acusaciones-de-plagio-contra-roy-lichtenstein",children:"Nuevas acusaciones de plagio contra Roy Lichtenstein"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.theguardian.com/artanddesign/2023/apr/09/new-allegations-of-plagiarism-against-roy-lichtenstein",children:"Original"}),'.\nSe han presentado nuevas acusaciones de plagio contra Roy Lichtenstein. Una nueva pel\xedcula afirma que cientos de sus obras pueden atribuirse a otros artistas. El documental afirma que m\xe1s de 30 artistas del c\xf3mic fueron "apropiados" por el fundador del movimiento del arte pop, que gan\xf3 millones con la venta de sus obras, mientras que los artistas originales copiados viv\xedan vidas austeras e incluso en la indigencia. Mientras algunos defienden la obra de Lichtenstein como "apropiaci\xf3n", los cr\xedticos la califican de robo, citando "plagios descarados" junto a obras "t\xe9cnica y art\xedsticamente" superiores copiadas por Lichtenstein.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35501868",children:"Discussion Service"}),".\nLas nuevas acusaciones de plagio contra Roy Lichtenstein suscitan un debate sobre \xe9tica, originalidad y adecuaci\xf3n en el mundo del arte. Los usuarios de Discussion Service debaten si la obra de Lichtenstein es una transformaci\xf3n o un robo descarado con cambios m\xednimos. Se plantean cuestiones de derechos de autor y propiedad intelectual, as\xed como sobre el valor cultural del c\xf3mic frente a las bellas artes. El debate incluye opiniones sobre la naturaleza del arte, la creaci\xf3n y el valor en el mundo del arte. Seg\xfan el art\xedculo, los dibujantes de c\xf3mics originales sol\xedan ser considerados mercanc\xedas mal pagadas."]})]})}function u(e={}){const{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}}}]);